import * as fs from 'fs';
import * as path from 'path';
import { applyFormDefaults, buildChartValues, seedFieldsFromValues } from '../chartValues';
import { deepMerge } from '../bindings';

/**
 * The Superset administrator, run against the REAL SUPERSET/service.json and superset-env.json. Its password is
 * generated by the server into a Secret, so the wizard neither asks for one nor sends one, and the break-glass local
 * sign-in (the only way that account signs in under a security profile) is off unless the operator turns it on.
 */
const servicesDir = path.join(__dirname, '../../../../../KDPS/services');
const def = JSON.parse(fs.readFileSync(path.join(servicesDir, 'SUPERSET/service.json'), 'utf8'));
const env = JSON.parse(fs.readFileSync(path.join(servicesDir, 'SUPERSET/configurations/superset-env.json'), 'utf8'));
const breakGlass = def.form.find((g: any) => g.name === 'adminConfig').fields
  .find((f: any) => f.name === 'global.security.auth.localLoginFallback');

const build = (formValues: any) => buildChartValues({
  form: def.form, bindings: def.bindings, variables: def.variables, formValues,
  retiredValues: def.retiredValues, chartVersion: def.version,
});

const install = (): any => {
  const values: any = { releaseName: 'superset', namespace: 'analytics' };
  applyFormDefaults(def.form, values);
  values.superset = { ...(values.superset || {}), secretKey: 'Key-1' };
  return values;
};

describe('Superset administrator login', () => {
  it('the break-glass local sign-in is a switch, off by default', () => {
    expect(breakGlass.type).toBe('boolean');
    expect(breakGlass.defaultValue).toBe(false);
    expect(breakGlass.excludeFromValues).toBeFalsy();
    expect(build(install()).global.security.auth.localLoginFallback).toBe(false);
  });

  it('turned on, it reaches the chart value that turns the fallback on', () => {
    const form = install();
    form.global.security.auth.localLoginFallback = true;
    expect(build(form).global.security.auth.localLoginFallback).toBe(true);
  });

  it('an upgrade keeps the setting the release runs with', () => {
    const deployed = { global: { security: { auth: { localLoginFallback: true } } } };
    const form: any = { releaseName: 'superset', namespace: 'analytics' };
    applyFormDefaults(def.form, form);
    deepMerge(form, deployed);
    seedFieldsFromValues(def.form, form);
    expect(build(form).global.security.auth.localLoginFallback).toBe(true);
  });

  it('the wizard asks for no administrator password and sends none', () => {
    expect(env.properties.map((p: any) => p.name)).not.toContain('SUPERSET_ADMIN_PASSWORD');
    const values = build(install());
    expect(values.init?.adminUser?.password).toBeUndefined();
    expect(JSON.stringify(values)).not.toMatch(/"password":"admin"/);
  });

  it('an upgrade drops the administrator password an earlier wizard sent', () => {
    const form = install();
    form['superset-env/SUPERSET_ADMIN_PASSWORD'] = 'Old-Admin-Pass-1';
    expect(JSON.stringify(build(form))).not.toContain('Old-Admin-Pass-1');
  });

  it('the server generates the administrator password into a Secret the chart reads', () => {
    const admin = def.generatedSecrets.find((s: any) => s.key === 'admin');
    expect(admin.secretNameTemplate).toBe('{{releaseName}}-superset-admin');
    expect(admin.values['init.adminUser.existingSecret']).toBe('{{secretName}}');
    expect(breakGlass.help).toContain('<release>-superset-admin');
  });
});
